import{_ as l,l as r,o as e,c as i,v as t,p as s,x as o,d as h,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"堆排序","description":"","frontmatter":{"title":"堆排序","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/heapsort.md","filePath":"cs/heapsort.md","lastUpdated":1789023840000}'),c={name:"cs/heapsort.md"};function E(A,a,B,m,_,T){const n=r("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="堆排序" tabindex="-1">堆排序 <a class="header-anchor" href="#堆排序" aria-label="Permalink to &quot;堆排序&quot;">​</a></h1><div class="epigraph"><p>堆把无序数组收成可反复取出极值的结构；排序就是建堆再反复弹出。</p><footer>—— 据 Williams, Algorithm 232: Heapsort, 1964；Floyd, Algorithm 245: Treesort 3, 1964；Knuth, TAOCP vol. 3 整理</footer></div><p>上一课<a href="/cs/insertion-merge">插入与归并</a>对照了前缀不变式与分治合并：一个最坏平方、一个最坏 \\(n\\log n\\) 但要线性缓冲。<a href="/cs/insertion-merge">堆与优先队列</a>已经能 \\(O(\\log n)\\) 取出最大元。本课不重建堆。缺口是：用同一数组上的堆完成就地排序，把「额外线性空间」从 \\(n\\log n\\) 比较排序里拿掉。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>归并的 \\(\\Theta(n\\log n)\\) 来自分治加线性合并，不是来自堆。若只反复从无序数组找最大再放到末尾，每轮扫描仍是平方。缺口因此不是新的比较模型，而是把已有的堆操作排成：<strong>建堆一次，再把根与未排序后缀的末元对换并下滤</strong>。终止时后缀从大到小填满，整表有序。</p><p>本课仍在比较排序里。稳定性默认放弃：相等键在下滤时可以越过彼此。线性时间排序是后课才离开比较模型。</p><h3 id="建堆不是-次插入" tabindex="-1">建堆不是 \\(n\\) 次插入 <a class="header-anchor" href="#建堆不是-次插入" aria-label="Permalink to &quot;建堆不是 $n$ 次插入&quot;">​</a></h3><p>从空堆插入 \\(n\\) 个是 \\(\\Theta(n\\log n)\\)。Floyd 自底向上：叶子已是堆，从最后一个非叶往根下滤，总代价 \\(\\Theta(n)\\)。排序阶段仍是 \\(n\\) 次 \\(\\Theta(\\log n)\\) 下滤，整体 \\(\\Theta(n\\log n)\\)。不要把建堆也写成 \\(n\\log n\\) 再加一遍。</p><p><span class="marginnote">Williams 给出堆排序；Floyd 把建堆收成线性。Knuth vol. 3 把同一数组既当堆又当输出区。优先队列课已有下滤，本课只排工序。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数组下标堆：父 \\(i\\) 的子为 \\(2i\\)、\\(2i+1\\)（或 \\(0\\) 基等价）。建堆后不变式：下标 \\(1..i\\) 是堆， \\(i+1..n\\) 是已就位的后缀且不小于堆中任何键。每轮：交换 \\(A[1]\\) 与 \\(A[i]\\)， \\(i\\leftarrow i-1\\)，对根下滤。</p>',11)),(e(),s(d,null,{default:o(()=>[p(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%97%A0%E5%BA%8F%E6%95%B0%E7%BB%84%22%5D%20--%3E%20BUILD%5B%22%E8%87%AA%E5%BA%95%E5%90%91%E4%B8%8A%E5%BB%BA%E5%A0%86%20%CE%98(n)%22%5D%0A%20%20BUILD%20--%3E%20SWAP%5B%22%E6%A0%B9%E4%B8%8E%E6%9C%AA%E6%8E%92%E5%BA%8F%E6%9C%AB%E5%85%83%E5%AF%B9%E6%8D%A2%22%5D%0A%20%20SWAP%20--%3E%20SIFT%5B%22%E4%B8%8B%E6%BB%A4%22%5D%0A%20%20SIFT%20--%3E%20DONE%5B%22%E5%90%8E%E7%BC%80%E5%B7%B2%E5%B0%B1%E4%BD%8D%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>正确性走<a href="/cs/loop-invariant">循环不变式</a>：后缀有序且是全局最大的那些键。代价：建堆线性，排序阶段 \\(\\Theta(n\\log n)\\)。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>就地：只占 \\(O(1)\\) 额外字（递归下滤可改成循环）。与归并对照：最坏同样 \\(n\\log n\\)，空间从 \\(\\Theta(n)\\) 降到常数，缓存上连续下滤与归并的顺序扫描不同，本课不量化。<a href="/cs/locality-principle">局部性</a>只提醒：堆不是顺序扫描。</p><p>下滤破坏稳定性。若要稳定的 \\(n\\log n\\) 就地，本课不提供；那不是堆的职责。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入快排分区，不证比较下界。键不是数轴上的计数对象。图算法里的优先队列仍用堆，但那是松弛不是排序——<a href="/cs/dijkstra">Dijkstra</a>才接。</p><p>后课默认：堆排序 = 线性建堆 + \\(n\\) 次下滤，最坏 \\(\\Theta(n\\log n)\\)，就地、不稳定。期望线性的分区是下一课的缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>堆排序把优先队列变成就地比较排序，最坏 \\(n\\log n\\)。</li><li>建堆 \\(\\Theta(n)\\)；不要写成 \\(n\\) 次插入。</li><li>默认不稳定；额外空间常数。</li><li>出处：Williams, 1964；Floyd, 1964；Knuth, TAOCP vol. 3；CLRS 第 6 章。</li></ul>',9))])}const g=l(c,[["render",E]]);export{f as __pageData,g as default};
